import{_ as r}from"./chunks/reports-menueband-ansichtund-abschnitt.BJvket7c.js";import{_ as t,o as n,c as a,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/reportverwaltung/reports-menueband-uebersicht.png",s="/bilder/reportverwaltung/reports-menueband-bearbeiten.png",o="/bilder/reportverwaltung/reports-menueband-allg-fkt.png",w=JSON.parse('{"title":"Das frühere Menüband der Reportverwaltung","description":"","frontmatter":{"title":"Das frühere Menüband der Reportverwaltung","source_pageid":1043,"source_revision":6528},"headers":[],"relativePath":"hilfe/fruehere-verfahren/menueband-reportverwaltung.md","filePath":"hilfe/fruehere-verfahren/menueband-reportverwaltung.md"}'),l={name:"hilfe/fruehere-verfahren/menueband-reportverwaltung.md"};function u(g,e,h,p,b,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="das-fruhere-menuband-der-reportverwaltung" tabindex="-1">Das frühere Menüband der Reportverwaltung <a class="header-anchor" href="#das-fruhere-menuband-der-reportverwaltung" aria-label="Permalink to &quot;Das frühere Menüband der Reportverwaltung&quot;">​</a></h1><p>Dieser Artikel beschreibt das frühere, im Wiki dokumentierte Menüband der Reportverwaltung. Für die Oberfläche von SchILD-NRW 3.6.0 verwenden Sie <a href="/reporting/reportverwaltung/menueband-reportverwaltung.html">Das Menüband der Reportverwaltung</a>.</p><p><a href="/bilder/reportverwaltung/reports-menueband-uebersicht.png"><img src="'+d+'" alt="Das frühere Menüband in der Reportverwaltung." loading="lazy"></a></p><p><em>Das frühere Menüband in der Reportverwaltung.</em></p><h2 id="reportbearbeitung" tabindex="-1">Reportbearbeitung <a class="header-anchor" href="#reportbearbeitung" aria-label="Permalink to &quot;Reportbearbeitung&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/reports-menueband-bearbeiten.png"><img src="'+s+'" alt="Der Bereich Reportbearbeitung bietet von Windows gewohnte Funktionen." loading="lazy"></a></p><p><em>Der Bereich Reportbearbeitung bietet von Windows gewohnte Funktionen.</em></p><table tabindex="0"><thead><tr><th>Frühere Funktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Neuen Report erzeugen</strong></td><td>Erstellt einen neuen, leeren Report im ausgewählten Ordner.</td></tr><tr><td><strong>Bearbeiten</strong></td><td>Öffnet den ausgewählten Report im Reporteditor.</td></tr><tr><td><strong>Kopieren</strong></td><td>Merkt den ausgewählten Report zum Kopieren vor. <strong>Einfügen</strong> erzeugt eine Kopie im Zielordner.</td></tr><tr><td><strong>Ausschneiden</strong></td><td>Merkt den Report zum Verschieben vor. Beim Einfügen an anderer Stelle wird das Original entfernt.</td></tr><tr><td><strong>Einfügen</strong></td><td>Fügt einen zum Kopieren oder Ausschneiden vorgemerkten Report ein.</td></tr></tbody></table><h2 id="allgemeine-reportfunktionen" tabindex="-1">Allgemeine Reportfunktionen <a class="header-anchor" href="#allgemeine-reportfunktionen" aria-label="Permalink to &quot;Allgemeine Reportfunktionen&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/reports-menueband-allg-fkt.png"><img src="'+o+'" alt="Der Bereich Allgemeine Reportfunktionen steuert im Hintergrund laufende Technik." loading="lazy"></a></p><p><em>Der Bereich Allgemeine Reportfunktionen steuert im Hintergrund laufende Technik.</em></p><table tabindex="0"><thead><tr><th>Frühere Funktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Verzeichnisbaum aktualisieren</strong></td><td>Liest die Ordnerstruktur neu ein, wenn Ordner oder Reports parallel im Windows-Explorer geändert wurden.</td></tr><tr><td><strong>Abfragen aktualisieren</strong></td><td>Aktualisiert bereits geladene Katalogdaten. Einige Tabellen, etwa die Fächerkataloge, wurden beim Programmstart in die Reportumgebung geladen. Eine später geänderte Fachbezeichnung konnte deshalb erst nach dem Aktualisieren in der Reportausgabe erscheinen.</td></tr><tr><td><strong>Druckerliste aktualisieren</strong></td><td>Liest die von Windows bereitgestellten Drucker neu ein.</td></tr><tr><td><strong>Info zu Standardformularen</strong></td><td>Zeigt die als Standard festgelegten Reports für Stammblatt und Schulbescheinigung.</td></tr><tr><td><strong>Info über Datenquellen</strong></td><td>Zeigt verfügbare Datenquellen, ihre Struktur und Datenbankfelder.</td></tr></tbody></table><p>Die Standardformulare wurden mit einem Rechtsklick auf den jeweiligen Report festgelegt. Anschließend ließen sich Stammblatt und Schulbescheinigung unter <strong>Individualdaten I ➜ Drucken</strong> aufrufen.</p><h2 id="ansicht-und-ausgewahltes-schuljahr" tabindex="-1">Ansicht und ausgewähltes Schuljahr <a class="header-anchor" href="#ansicht-und-ausgewahltes-schuljahr" aria-label="Permalink to &quot;Ansicht und ausgewähltes Schuljahr&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/reports-menueband-ansichtund-abschnitt.png"><img src="'+r+'" alt="Die Bereiche Ansicht und Ausgewähltes Schuljahr." loading="lazy"></a></p><p><em>Die Bereiche Ansicht und Ausgewähltes Schuljahr.</em></p><p><strong>Details</strong> zeigte Dateiname, Dateigröße sowie Datum und Uhrzeit der letzten Änderung; <strong>Liste</strong> zeigte nur den Dateinamen. Der Zeitstempel half, den Stand einer Reportdatei zu erkennen.</p><p>Über <strong>Schuljahr/Abschnitt</strong> wurde der Lernabschnitt als Datengrundlage ausgewählt. So konnte beispielsweise nach dem Abschnittswechsel noch ein Abgangszeugnis mit den Daten des vorherigen Abschnitts ausgegeben werden.</p><p>Anschließend musste wieder der aktuelle Abschnitt eingestellt werden, damit weitere Reports nicht mit Daten des falschen Abschnitts erzeugt wurden. Diesen Arbeitsablauf erläutert <a href="/reporting/reportverwaltung/daten-aus-zurueckliegenden-abschnitten-drucken.html">Daten aus zurückliegenden Abschnitten drucken</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Men%C3%BCband_(Reportverwaltung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6528.</p>',21)])])}const k=t(l,[["render",u]]);export{w as __pageData,k as default};
